async function runPendingNetworkObserver(durationMs=45000) {
  const state=load("replyPendingNetworkAfterFixObserverState");
  if(!state||state.halt_requested||state.status==="PENDING_NETWORK_CAPTURED"||state.status==="TERMINAL_NEEDS_RECONCILIATION") {text({status:state?.status,hash:state?.hash});return;}
  const parseTool=(r)=>{if(r.isError)throw Error(JSON.stringify(r));for(const c of r.content??[])if(c.type==="text"){try{return JSON.parse(c.text);}catch{}}throw Error("Expected JSON tool result");};
  const snapshot=async(label)=>{
    const r=await tools.mcp__node_repl__js({code:"console.log(JSON.stringify(await releaseNetworkCapture("+JSON.stringify(label)+")));",title:"Record live wallet and recovery status",timeout_ms:10000});
    state.raw_calls.push({kind:"browser_snapshot",result:r});store("replyPendingNetworkAfterFixObserverState",state);
    const observation=parseTool(r);state.observations.push(observation);store("replyPendingNetworkAfterFixObserverState",state);return observation;
  };
  state.active=true;state.status="CAPTURING";state.cycle_started_at=new Date().toISOString();store("replyPendingNetworkAfterFixObserverState",state);
  const started=Date.now();
  const first=await snapshot("active_capture_armed_before_human_approval");
  text({observer:"ACTIVE",wallet:first.visible.account,unsigned_confirmation:first.visible.consent_dialog_open,hash:first.visible.hash});
  await yield_control();
  while(Date.now()-started<durationMs){
    try{
      const before=await snapshot("before_public_receipt_sample");
      if(before.snapshot.includes("WALLET OUTCOME UNKNOWN")) {state.active=false;state.status="UNKNOWN_WALLET_OUTCOME_STOPPED";state.halt_requested=true;store("replyPendingNetworkAfterFixObserverState",state);text({status:state.status,hash:state.hash,wallet:before.visible.account,note:"No resubmission; inspect wallet Activity."});return;}
      const visibleHash=before.visible.hash;
      if(visibleHash){
        if(state.prohibited_hashes.includes(visibleHash))throw Error("Old completed hash is not eligible for this retry");
        if(state.hash&&state.hash!==visibleHash)throw Error("Recovery hash changed during one-request test");
        if(!before.visible.recovery_signer_b)throw Error("Observed recovery signer does not match B");
        if(!state.hash){state.hash=visibleHash;store("replyPendingNetworkAfterFixObserverState",state);notify({fresh_hash:visibleHash,observed_wallet:before.visible.account});}
        if(!state.exported){
          const ex=await tools.mcp__node_repl__js({code:"console.log(JSON.stringify(await releaseNetworkExportRecovery("+JSON.stringify(visibleHash)+")));",title:"Export the fresh recovery record",timeout_ms:10000});
          state.raw_calls.push({kind:"region_scoped_export",result:ex});store("replyPendingNetworkAfterFixObserverState",state);
          const exported=parseTool(ex);if(exported.hash!==visibleHash||!exported.exported)throw Error("Recovery export was not confirmed");
          state.exported=true;state.export_observation=exported;store("replyPendingNetworkAfterFixObserverState",state);
        }
        let r=await tools.exec_command({cmd:"node evidence/human-wallet/preflights/capture-recovery-receipt.mjs "+visibleHash,workdir:"C:/Users/user/Documents/genlayer/reply-check",max_output_tokens:16000,yield_time_ms:10000});
        state.raw_calls.push({kind:"receipt_command",result:r});store("replyPendingNetworkAfterFixObserverState",state);
        let output=r.output;
        if(r.session_id){
          state.receipt_session=r.session_id;store("replyPendingNetworkAfterFixObserverState",state);
          r=await tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:1000,max_output_tokens:16000});
          output+=r.output;state.raw_calls.push({kind:"receipt_poll",result:r});store("replyPendingNetworkAfterFixObserverState",state);
          if(r.session_id){state.status="RECEIPT_COMMAND_STILL_RUNNING";state.receipt_command_output=output;state.active=false;store("replyPendingNetworkAfterFixObserverState",state);text({status:state.status,session_id:r.session_id,hash:state.hash});return;}
        }
        if(r.exit_code!==0){state.errors.push({stage:"receipt_capture",at:new Date().toISOString(),output});store("replyPendingNetworkAfterFixObserverState",state);}
        else{
          const raw=output.replace(/\r\n/g,"\n"),start="REPLYCHECK_RECEIPT_RESULT\n",end="\nREPLYCHECK_RECEIPT_END",a=raw.indexOf(start),b=raw.lastIndexOf(end);
          if(a<0||b<a)throw Error("Receipt output saved but JSON markers missing");
          const capture=JSON.parse(raw.slice(a+start.length,b));
          const after=await snapshot("after_public_receipt_sample");
          const eligibleUi=o=>o.visible.off_studionet_ui&&o.visible.pending_ui&&!o.visible.terminal_ui&&o.visible.recovery_signer_b&&o.visible.valid_draft_denied&&o.visible.hash===state.hash;
          const bracketed=Date.parse(before.snapshotCompletedAt)<=Date.parse(capture.requested_at_utc)&&Date.parse(capture.requested_at_utc)<=Date.parse(capture.observed_at_utc)&&Date.parse(capture.observed_at_utc)<=Date.parse(after.snapshotRequestedAt);
          const passed=eligibleUi(before)&&eligibleUi(after)&&bracketed&&capture.expected.hash===state.hash&&capture.execution.state==="pending"&&capture.fixture_verified===true&&capture.exact_call_verified===true;
          const window={before,capture,after,bracketed_timestamps:bracketed,pending_network_observed:passed};
          state.windows.push(window);state.last_receipt=capture;store("replyPendingNetworkAfterFixObserverState",state);
          if(passed){state.active=false;state.status="PENDING_NETWORK_CAPTURED";state.passing_window_index=state.windows.length-1;store("replyPendingNetworkAfterFixObserverState",state);text({status:state.status,hash:state.hash,receipt_status:capture.receipt.status,observed_at:capture.observed_at_utc,windows:state.windows.length});return;}
          if(["success","failed"].includes(capture.execution.state)){state.active=false;state.status="TERMINAL_NEEDS_RECONCILIATION";store("replyPendingNetworkAfterFixObserverState",state);text({status:state.status,hash:state.hash,execution:capture.execution.state,wallet:after.visible.account,pending_network_observed:false});return;}
        }
      }
    }catch(error){
      state.errors.push({stage:"observer",at:new Date().toISOString(),message:String(error)});state.active=false;state.status="OBSERVER_NEEDS_ATTENTION";store("replyPendingNetworkAfterFixObserverState",state);text({status:state.status,error:String(error),hash:state.hash});return;
    }
    await new Promise(resolve=>setTimeout(resolve,3000));
  }
  state.active=false;state.status="CYCLE_COMPLETE_CAN_CONTINUE";store("replyPendingNetworkAfterFixObserverState",state);
  text({status:state.status,hash:state.hash,latest:state.observations.at(-1)?.visible,windows:state.windows.length});
}
